    components = []

    # The colored cell is a seed for its 4-connected nonzero region.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            colors = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                if grid[y][x] not in (0, 1):
                    colors.append((y, x, grid[y][x]))
                for dy, dx in neighbors:
